-- BOOK-INGEST-AUDIT.md F59: a class states how its level-up spells are bounded,
-- and the app ignored it. Two shapes, four classes.
--
-- THE OCEAN PAIR. `spells_per_level_from: true` is read by nothing - the only
-- reader, leveling.js spellNamesForGrant, wants an ARRAY and only for a
-- schedule entry saying `from_list: true`. Underseas printed 60 (the Ocean
-- Wizard) and printed 151 (the Koral Shaper) give one spell per level "equal or
-- below his own experience level" / "cannot exceed the character's current
-- level" and name no list for it, read from the cache 2026-09-11. So the key
-- goes and nothing else about the pick changes: it stays capped by
-- `spells_per_level_levels: up_to_character_level` and reaches the ocean spells
-- and the general invocations through F57's `spell_traditions_allowed`.
-- Binding it to the ocean list instead would DROP the cap - a named list
-- replaces the level cap in the wizard, the sheet and the validator - which a
-- data-only change cannot prevent. The Ocean Wizard's two sentences reading the
-- pick as ocean-list-only are corrected to say what the book and the app do.
--
-- THE LYN-SRIAL PAIR. New West printed 135: the Sky-Knight gains "one
-- additional spell every level of experience, starting with level one, from
-- any category except Clouds of Creation", the Cloudweaver "two additional
-- Cloud spells for every level ... from any category except Clouds of War".
-- Their 50- and 45-name lists sat in `spells_from`, which only a STARTING pick
-- reads, and neither class stated a starting count - so the lists bounded
-- nothing, level one granted no pick, and every level-up reached the excluded
-- category. Each list is now declared once in `spell_lists`, read by a
-- starting group (level one) and by `spells_schedule` entries for levels 2-15,
-- which replace `spells_per_level` - a schedule is the complete statement when
-- present. The shape is the Shifter's and the Elemental Fusionists'.

UPDATE imported_classes
   SET markdown = replace(replace(replace(markdown,
         replace('~~  spells_per_level_from: true~~', '~~', char(10)),
         replace('~~', '~~', char(10))),
         'It is the ocean list and nothing else.',
         'Its level-gated picks reach the ocean spells and the general invocations it starts with (Breathe Without Air is one), never dolphin magic or spellsongs - BOOK-INGEST-AUDIT.md F57 and F59.'),
         'but a spell every level drawn from the whole ocean list,',
         'but a spell every level, no higher than its own level, from the ocean spells or the general invocations - printed 60 names no list for that pick (BOOK-INGEST-AUDIT.md F59) -'),
       updated_at = datetime('now')
 WHERE class_id = 'ocean-wizard' AND instr(markdown, replace('~~  spells_per_level_from: true~~', '~~', char(10))) > 0;

