SELECT 'no live class carries spells_per_level_from: true' AS assertion, count(*) AS got, 0 AS want
  FROM imported_classes WHERE deleted_at IS NULL AND instr(markdown, 'spells_per_level_from: true') > 0;
SELECT 'both Lyn-Srial classes draw every spell pick from a declared list' AS assertion, count(*) AS got, 2 AS want
  FROM imported_classes WHERE deleted_at IS NULL
   AND class_id IN ('lyn-srial-sky-knight', 'lyn-srial-cloudweaver')
   AND instr(markdown, char(10) || '  spells_schedule:') > 0
   AND instr(markdown, 'from_list: "any_but_') > 0
   AND instr(markdown, char(10) || '  spells_from:') = 0;
SELECT 'neither says a flat count carries the per-level pick' AS assertion, count(*) AS got, 0 AS want
  FROM imported_classes WHERE deleted_at IS NULL AND instr(markdown, 'carries the per-level pick') > 0;
SELECT 'the Ocean Wizard no longer reads its pick as the ocean list alone' AS assertion, count(*) AS got, 0 AS want
  FROM imported_classes WHERE class_id = 'ocean-wizard'
   AND (instr(markdown, 'ocean list and nothing else') > 0 OR instr(markdown, 'drawn from the whole ocean list') > 0);

